package com.payguard.payment.outbox; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="outbox") public class OutboxEntry { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="event_id",nullable=false,unique=true) private String eventId; @Column(name="aggregate_id",nullable=false) private String aggregateId; @Column(name="event_type",nullable=false) private String eventType; @Column(nullable=false) private String topic; @Column(name="partition_key",nullable=false) private String partitionKey; @Column(nullable=false,columnDefinition="text") private String payload; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="published_at") private Instant publishedAt; protected OutboxEntry(){} public OutboxEntry(String eid,String aid,String type,String topic,String key,String payload){eventId=eid;aggregateId=aid;eventType=type;this.topic=topic;partitionKey=key;this.payload=payload;} @PrePersist void created(){createdAt=Instant.now();} public String getTopic(){return topic;} public String getPartitionKey(){return partitionKey;} public String getPayload(){return payload;} public void published(){publishedAt=Instant.now();} }
